#!/usr/bin/env python3
"""Rebuild the self-contained tutorial: python3 scripts/generate_tutorial.py."""
from pathlib import Path
from html import escape
from urllib.parse import quote
import json
from tutorial_content import UNITS, SOURCES, FORMULAS
from tutorial_models import MODELS
from tutorial_university import NOTES, FOUNDATIONS
from tutorial_university_render import render_guide, render_tutor, render_reading_map, university_outline
ROOT = Path(__file__).resolve().parent.parent

def e(s): return escape(str(s), quote=True)
def paragraphs(s): return ''.join(f'<p>{e(p.strip())}</p>' for p in s.strip().split('\n\n'))
def pdf(path,label,page=None):
    href=quote(path,safe='/')+(f'#page={page}' if page else '')
    return f'<a href="{href}" target="_blank" rel="noopener">{e(label)} ↗</a>'
def eq(s): return f'<div class="equation" data-copy><span>{e(s)}</span><button class="copy-button" type="button" aria-label="Copy formula">Copy</button></div>'
def link(id,label): return f'<a href="#{e(id)}">{e(label)}</a>'
def lesson_refs(uid,lid):
    return ' · '.join(pdf(s[0],s[1]) for s in SOURCES if lid in s[4])

nav=link('overview','⌂  Course overview')+link('tutor-guide','T  Tutor explanations')+link('formula-trees','↳  Formula trees')+''.join(link(u['id'],f'{i:02d}  {u["title"]}') for i,u in enumerate(UNITS,1))+link('formula-sheet','ƒ  Formula sheet')+link('lecture-index','↗  Lecture index')
cards=''.join(f'<a class="unit-card" href="#{u["id"]}"><div class="card-top"><span class="card-symbol">{u["symbol"]}</span><span class="card-num">CHAPTER {i:02d}</span></div><h3>{e(u["title"])}</h3><p>{e(u["subtitle"])}</p><div class="card-bottom"><span>{len(u["lessons"])} lessons · 2 examples · 3 questions</span><b>→</b></div></a>' for i,u in enumerate(UNITS,1))
hero='''<svg class="hero-art" viewBox="0 0 450 340" role="img" aria-labelledby="hero-title"><title id="hero-title">A stylized molecular network connecting observation, particles, and calculation</title><ellipse class="orbital" cx="227" cy="170" rx="177" ry="90" transform="rotate(-27 227 170)"/><ellipse class="orbital" cx="227" cy="170" rx="144" ry="130" transform="rotate(24 227 170)"/><path d="M91 145 193 99 294 160 235 249 125 244M193 99 235 249M294 160 366 96" fill="none" stroke="#b9c7ad" stroke-width="13" stroke-linecap="round"/><circle cx="91" cy="145" r="33" fill="#235b47"/><circle cx="193" cy="99" r="44" fill="#dfeab7"/><circle cx="294" cy="160" r="49" fill="#235b47"/><circle cx="235" cy="249" r="35" fill="#d46a43"/><circle cx="125" cy="244" r="22" fill="#e3eacb"/><circle cx="366" cy="96" r="22" fill="#d46a43"/><g font-size="11" fill="#64716a"><text x="28" y="52">OBSERVE</text><text x="302" y="291">EXPLAIN</text><text x="323" y="44">CALCULATE</text></g><text x="177" y="107" font-size="23" fill="#235b47">C</text><text x="282" y="169" font-size="25" fill="white">O</text><text x="224" y="256" font-size="20" fill="white">H</text><path d="M30 65h61M320 303h72" stroke="#b9c7ad"/></svg>'''
guide=render_guide(UNITS,e,paragraphs,eq,pdf,link)
trees='<section class="tutor-guide searchable" id="formula-trees" aria-labelledby="trees-title"><div class="section-title"><h2 id="trees-title">See where the formulas come from</h2><span>Eight paths from definitions to applications</span></div><p>Follow each branch into the full lesson. A formula becomes easier to choose when you know the definition and conservation rule behind it.</p><div class="section-tools"><button type="button" data-tree-expand="true">Open all formula trees</button><button type="button" data-tree-expand="false">Close formula trees</button></div>'
for i,u in enumerate(UNITS,1):
    title,derivation,example,conditions,target=u['tree']
    trees+=f'<details class="formula-tree" id="tree-{u["id"]}"><summary>{i:02d} · {e(title)}</summary><div class="tree-body"><div class="tree-steps"><p><strong>Start with the definitions.</strong> {e(derivation)}</p><p><strong>Check an example.</strong> {e(example)}</p><p><strong>Keep the conditions.</strong> {e(conditions)}</p></div>{link(target,"Follow this branch into the lesson →")} · {link("tutor-"+target,"University explanation & derivation →")} · {link("foundations","Revisit the shared foundations")}</div></details>'
trees+='</section>'
units_html=''
quiz_data={}
for i,u in enumerate(UNITS,1):
    uid=u['id']
    section=f'<section class="lesson-unit searchable" id="{uid}" aria-labelledby="heading-{uid}"><div class="unit-heading"><span class="big-num">{i:02d}</span><div><h2 id="heading-{uid}">{e(u["title"])}</h2><p>{e(u["subtitle"])}</p></div></div><p class="unit-question">{e(u["question"])}</p>'
    for j,l in enumerate(u['lessons'],1):
        lid=f'{uid}-{j}'
        tutor=render_tutor(lid,l,f'{i}.{j}',e,paragraphs,eq,pdf,link)
        lecture_refs=lesson_refs(uid,lid)
        section+=f'<details class="lesson" id="{lid}"'+(' open' if j==1 else '')+f'><summary><span class="lesson-index">{i}.{j}</span>{e(l["title"])}</summary><div class="lesson-body">{paragraphs(l["idea"])}{eq(l["equation"])}<div class="trap"><strong>Common trap</strong>{e(l["trap"])}</div>{tutor}<p class="source-links">{pdf("chem11.pdf",f"Textbook · PDF {l["page"]}",l["page"])}'+(' · '+lecture_refs if lecture_refs else '')+'</p></div></details>'

    section+=MODELS[uid]+'<h3 class="mini-title">Put the ideas to work</h3><div class="example-grid">'
    for j,(title,prompt,steps) in enumerate(u['examples'],1):
        section+=f'<article class="example"><div class="eyebrow">Worked example {i}.{j}</div><h4>{e(title)}</h4><p>{e(prompt)}</p><details class="solution"><summary>Reveal worked solution</summary><ol>'+''.join(f'<li>{e(step)}</li>' for step in steps)+'</ol></details></article>'
    section+='</div>'+f'<form class="quiz" data-unit="{uid}" aria-labelledby="quiz-{uid}"><h3 id="quiz-{uid}">Check your understanding</h3><p>Choose answers, then check the reasoning. You can try again.</p>'
    quiz_data[uid]=[]
    for j,(q,options,answer,explanation) in enumerate(u['quiz']):
        section+=f'<fieldset><legend>{j+1}. {e(q)}</legend><div class="options">'+''.join(f'<label class="option"><input type="radio" name="{uid}-q{j}" value="{k}">{e(o)}</label>' for k,o in enumerate(options))+f'</div><p class="feedback" id="{uid}-feedback{j}" hidden></p></fieldset>'
        quiz_data[uid].append(dict(answer=answer,explanation=explanation))
    section+='<div class="quiz-footer"><button class="primary" type="submit">Check answers</button><span class="quiz-score" role="status" aria-live="polite"></span></div></form>'
    section+=f'<div class="unit-footer"><div class="resources">{link("tree-"+uid,"Explain the formula →")} {link("lecture-index","Find lecture practice ↗")}</div><label class="complete-label"><input class="complete" type="checkbox" data-unit="{uid}">Mark chapter reviewed</label></div></section>'
    units_html+=section
formulas='<section class="toolbox searchable" id="formula-sheet" aria-labelledby="formula-title"><div class="section-title"><h2 id="formula-title">Keep the essentials close.</h2><span>Formula sheet · copy with a button or double-click</span></div><p class="lesson-intro">The symbol M can mean molar mass in an equation or mol L⁻¹ after a concentration value; read its context. Keep guard digits and round the final measured result.</p><div class="formula-grid">'
for title,formula,note,target in FORMULAS:
    formulas+=f'<article class="formula-item"><h3>{e(title)}</h3>{eq(formula)}<p>{e(note)}</p>{link(target,"Explain this formula →")} · {link("tutor-"+target,"University reasoning →")}</article>'
formulas+='</div></section>'
sources='''<section class="source-note searchable" id="lecture-index" aria-labelledby="sources-title"><h2 id="sources-title">Your lecture notes, connected.</h2><p>The eight chapters follow the supplied course outline and <em>BC Science Chemistry 11</em> (Edvantage Interactive, 2011). All 15 course-outline, lecture, practice, answer, and lab-report PDFs below were examined with text extraction or OCR: 162 pages in total. Scan recognition is imperfect; the source PDFs preserve handwriting and diagrams. This page explains their topics in original wording rather than transcribing every worksheet question or handwritten answer.</p>'''
sources+='<div class="table-scroll"><table class="study-table"><caption>Lecture and practice map · page numbers are PDF viewer pages</caption><thead><tr><th scope="col">Source PDF</th><th scope="col">Topics and page ranges</th><th scope="col">Study these lessons</th></tr></thead><tbody>'
for path,label,pages,scope,targets in SOURCES:
    # One representative link per target; all targets exist in the page.
    sources+=f'<tr><th scope="row">{pdf(path,label)}<br><small>{pages} page'+('s' if pages!=1 else '')+f'</small></th><td>{e(scope)}</td><td>'+ ' · '.join(link(t,next((f'{i}.{j}' for i,u in enumerate(UNITS,1) for j,l in enumerate(u['lessons'],1) if f'{u["id"]}-{j}'==t),next((u['title'] for u in UNITS if u['id']==t),t))) for t in targets)+'</td></tr>'
sources+='</tbody></table></div><h3>Textbook reading map</h3><p>The main textbook is '+pdf('chem11.pdf','BC Science Chemistry 11 · complete 452-page PDF')+'. The identically titled scan and the linked copy in this folder are alternate copies of the same course text. PDF page numbers are used to avoid confusion with printed page numbers.</p><div class="table-scroll"><table class="study-table"><thead><tr><th scope="col">Chapter</th><th scope="col">Read in the main textbook</th><th scope="col">Focus</th></tr></thead><tbody>'
for i,(u,start,end) in enumerate(zip(UNITS,[7,65,113,167,239,291,369,407],[64,112,166,238,290,368,406,452]),1):
    sources+=f'<tr><th scope="row">{i}. {e(u["title"])}</th><td>{pdf("chem11.pdf",f"PDF pages {start}–{end}",start)}</td><td>{e(u["subtitle"])}</td></tr>'
sources+='</tbody></table></div><p><strong>Additional local textbook reading.</strong> '+pdf('Chemistry_The_Central_Science.pdf','Chemistry: The Central Science')+'; '+pdf('ModernChemistry.pdf','Modern Chemistry')+'; '+pdf('Chapter3Modern.pdf','Atomic Shells and Classical Models of Chemical Bonding')+'. These university books support the expanded tutor explanations and their worked derivations. The course notes and BC textbook set the student-level tutorial scope.</p><p><strong>Class conventions.</strong> Gas worksheets use about 22.4 L mol⁻¹ for 0 °C and 1 atm; other STP definitions give different values. The bonding notes use approximate ΔEN boundaries of 0.4 and 1.7. Transition-metal valence counting follows the convention stated in the atomic lesson. Simplified answer-sheet statements are explained with their limits, including resonance, ion electron configurations, and expanded-octet Lewis diagrams.</p><p><strong>Lab-report route.</strong> Use identification and title, abstract, purpose, materials, procedure, data/observations, results, discussion, and conclusion as specified in the supplied report guide. Write the abstract after the investigation, include units and a representative calculation, and tie the conclusion to the purpose. The sample magnesium–acid report illustrates writing structure; a few trial times alone do not establish a universal maximum reaction rate.</p><p>Organic chemistry is marked as an additional unit in the supplied course outline and is included here from textbook chapter 8. Titrations are also included from textbook §7.4. Work through original assignments separately; the lecture links retain the full practice and worked companions.</p><p class="lesson-intro">All lessons, diagrams, quizzes, formula trees, and models work offline. PDF links need the source files in their existing paths relative to this page. Design follows '+ '<a href="https://cghuisunshine.github.io/Chemistry12/tutorial.html" target="_blank" rel="noopener">your Chemistry 12 study companion ↗</a>. Progress is stored only in this browser.</p></section>'
sources=sources.replace('</section>',render_reading_map(e,pdf)+'</section>')
css=(ROOT/'scripts/tutorial.css').read_text()
js=(ROOT/'scripts/tutorial.js').read_text()
html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Chemistry 11: 42 lessons from all local lecture-note PDFs and the BC textbook, with 42 university tutor explanations, 21 worked derivations, ten shared foundations, worked examples, quizzes and interactive models."><meta name="theme-color" content="#235b47"><title>Chemistry 11 — A study companion</title><style>{css}</style></head><body>
<a class="skip" href="#main">Skip to tutorial</a><aside class="sidebar" id="sidebar" aria-label="Course navigation"><a class="brand" href="#overview"><span class="brand-icon">C</span>Chemistry 11</a><p class="eyebrow">Your study companion</p><nav aria-label="Chapters and resources">{nav}</nav><div class="side-progress"><p>Your learning journey</p><progress id="courseProgress" max="8" value="0" aria-label="Chapters reviewed"></progress><p id="progressText">0 of 8 chapters reviewed</p><small id="storageNote">Progress saves in this browser.</small></div><div class="side-foot">Learn the idea. Work an example.<br>Explain why. Test your understanding.<br><a href="#lecture-index">Your lecture notes & textbook ↗</a></div></aside><button type="button" id="backdrop" class="backdrop" aria-label="Close navigation"></button><div class="shell"><header class="topbar"><button type="button" id="menuBtn" class="mobile-toggle" aria-controls="sidebar" aria-expanded="false">☰ <span class="visually-hidden">Navigation</span></button><div class="breadcrumb">Science &nbsp; / &nbsp; <strong>Chemistry 11</strong></div><div class="top-actions"><label class="visually-hidden" for="search">Search tutorial topics</label><input class="search" id="search" type="search" placeholder="Search a topic…"><button type="button" id="printBtn">Print / PDF ↗</button></div></header><main id="main" class="content"><noscript><p class="no-js">All lesson text and worked solutions are readable without JavaScript. Enable it for search, quizzes, models, and saved progress.</p></noscript><section id="overview" aria-labelledby="course-title"><div class="hero"><div><span class="tag"><span class="dot"></span>Grade 11 · Chemistry</span><h1>Make sense of<br><em>chemistry.</em></h1><p>Your lecture notes and textbook, connected. Understand the particles, follow the calculations, and see why the chemistry works.</p><div class="hero-actions"><a class="primary" style="padding:10px 17px;border-radius:8px;text-decoration:none;font-size:12px" href="#skills">Start learning &nbsp; →</a><a class="text-link" href="#lecture-index">Find a lecture</a></div><div class="stats"><span><strong>8</strong> chapters</span><span><strong>42</strong> lessons</span><span><strong>16</strong> worked examples</span></div></div>{hero}</div><div class="section-title"><h2 id="course-title">Your course, at a glance</h2><span>Follow the sequence. Connect the ideas.</span></div><div class="roadmap">{cards}</div><div class="howto"><strong>A little practice goes a long way.</strong><p>Read the idea, explain it in your own words, try the worked example, then check your understanding. Use the tutor notes and formula trees whenever a step needs a reason.</p></div></section><div class="section-title"><h2>The tutorial</h2><div class="section-tools"><button type="button" data-expand="true">Expand all</button><button type="button" data-expand="false">Collapse all</button></div></div><p class="lesson-intro">24 quiz questions · 8 interactive models · 8 formula trees · 42 university tutor explanations · 21 worked derivations. Formula boxes have copy buttons and support double-click copying.</p><p id="searchStatus" class="lesson-intro" role="status" aria-live="polite"></p><div id="emptySearch" class="empty" hidden>No matching topic. Try “mole”, “naming”, “orbitals”, or “polarity”.</div>{guide}{trees}{units_html}{formulas}{sources}<footer class="footer"><span>Chemistry 11 · Built for curiosity, understanding, and practice.</span><button type="button" id="resetProgress">Reset review progress</button><a href="#overview">Back to top ↑</a></footer></main></div><div class="toast" id="toast" role="status" hidden></div><script id="studyPageStructure" type="application/json">{json.dumps([dict(id=u['id'],title=u['title'],lessons=[l['title'] for l in u['lessons']]) for u in UNITS])}</script><script>const quizData={json.dumps(quiz_data)};\n{js}</script></body></html>'''
(ROOT/'tutorial.html').write_text(html)
outline=['# Chemistry 11 — A study companion','\nEight chapters based on the local lecture-note PDFs and BC Science Chemistry 11.']
for i,u in enumerate(UNITS,1):
    outline += [f'\n## {i}. {u["title"]}',u['question']]
    for j,l in enumerate(u['lessons'],1):
        outline += [f'\n### {i}.{j} {l["title"]}',l['idea'],f'\n`{l["equation"]}`',f'\nCommon trap: {l["trap"]}','\nTutor explanation: '+l['why'],'\nCheck: '+l['check'],f'\nTextbook: chem11.pdf#page={l["page"]}']
(ROOT/'docs/tutorial-outline.md').write_text('\n\n'.join(outline)+university_outline(UNITS))
print(f'Built tutorial.html: {len(html):,} characters; {sum(len(u["lessons"]) for u in UNITS)} lessons, {len(SOURCES)} course PDFs, {sum(s[2] for s in SOURCES)} note pages.')
